  if(!cache.has(p.game)){const response=await fetch(`data/tracking/${p.game}.json`);if(!response.ok)throw new Error('Tracking file could not be loaded.');const bundle=await response.json();cache.set(p.game,bundle);if(cache.size>5)cache.delete(cache.keys().next().value);}
