  const snap=replay.snap,throwAt=findEvent('pass_forward'),sackAt=findEvent('qb_sack'),end=throwAt??sackAt;
  $('timing').textContent=snap!==null&&end!==null?`${replay.frames[end][1].toFixed(1)}s · ${throwAt!==null?'throw':'sack'}`:'Not tagged';
  const events=[[snap,'Snap'],[throwAt,'Throw'],[sackAt,'Sack'],[replay.frames.length-1,'End']].filter(([i])=>i!==null);
