 const f=replay.frames[frame],snap=replay.frames[replay.snap??0],ball=replay.players.findIndex(p=>p.team==='football'),qb=replay.players.findIndex(p=>p.id===selected.qb);
 const los=ball>=0?snap[3][ball*2]:60,qby=qb>=0?snap[3][qb*2+1]:26.67;
 // Equal yard scale; a stable crop contains both highlighted players through the observed window.
 const span=zoom&&camera?camera.span:120,scale=(w-36)/span,yspan=(h-36)/scale;
 const x0=zoom&&camera?camera.x0:0,y0=zoom&&camera?camera.y0:(160/3-yspan)/2;
