  const fontSize=Math.max(17,Math.min(30,11*1040/canvas.clientWidth));ctx.font=`600 ${fontSize}px Arial`;const text=`#${p.jersey} ${playerName(id).split(' ').slice(-1)[0]} · ${id===selected.qb?'QUARTERBACK':'WATCH'}`;
