  const candidates=[[-bw-36,-bh-18],[36,-bh-18],[-bw-36,26],[36,26],[0,-bh-56]].map(([dx,dy])=>({x:Math.max(22,Math.min(w-bw-22,px+dx)),y:Math.max(40,Math.min(h-bh-35,py+dy)),w:bw,h:bh}));
